  reportsDesc: { en: 'Structured, evidence-backed inspection summaries detailing validated findings, observations, and recommendations.', hi: 'सत्यापित निष्कर्षों, टिप्पणियों और अनुशंसाओं वाली संरचित, साक्ष्य-आधारित जाँच रिपोर्ट।', mr: 'पडताळलेले निष्कर्ष, निरीक्षणे आणि शिफारशींचे संरचित, पुरावा-आधारित तपासणी सारांश.' },
  officerDesc: { en: 'Available officer dashboard and local review queue. Review decisions and reporting are planned in Module 05.', hi: 'अधिकारी डैशबोर्ड और स्थानीय समीक्षा कतार उपलब्ध है। समीक्षा निर्णय और रिपोर्टिंग मॉड्यूल 05 में नियोजित हैं।', mr: 'अधिकारी डॅशबोर्ड आणि स्थानिक पुनरावलोकन रांग उपलब्ध आहे. निर्णय आणि अहवाल मॉड्यूल 05 मध्ये नियोजित आहेत.' },
  registerStep: { en: 'Register as an Institution Coordinator or Review Officer in your local prototype workspace.', hi: 'स्थानीय प्रोटोटाइप कार्यस्थान में संस्थान समन्वयक या समीक्षा अधिकारी के रूप में पंजीकरण करें।', mr: 'स्थानिक प्रोटोटाइप कार्यक्षेत्रात संस्था समन्वयक किंवा पुनरावलोकन अधिकारी म्हणून नोंदणी करा.' },
  submitStep: { en: 'Enter institutional parameters and upload required supporting dossiers and statutory clearances.', hi: 'संस्थान के मापदंड दर्ज करें और आवश्यक सहायक अभिलेख व वैधानिक मंज़ूरियाँ अपलोड करें।', mr: 'संस्थेचे निकष प्रविष्ट करा आणि आवश्यक सहाय्यक संचिका व वैधानिक परवानग्या अपलोड करा.' },
  validateStep: { en: 'OCR text extraction, document anomaly detection, and AI-assisted verification analysis.', hi: 'OCR पाठ निष्कर्षण, दस्तावेज़ विसंगति पहचान और AI-सहायित सत्यापन विश्लेषण।', mr: 'OCR मजकूर निष्कर्षण, दस्तऐवज विसंगती शोध आणि AI-सहाय्यित पडताळणी विश्लेषण.' },
  resultsStep: { en: 'Rule-based compliance checks, verification summaries, and human officer scrutiny decisions.', hi: 'नियम-आधारित अनुपालन जाँच, सत्यापन सारांश और मानवीय अधिकारी जाँच निर्णय।', mr: 'नियम-आधारित नियमपालन तपासणी, पडताळणी सारांश आणि मानवी अधिकारी छाननी निर्णय.' },
  benefitOne: { en: 'Browser-local applications, supporting document uploads, and editable drafts are available in Module 03.', hi: 'ब्राउज़र-स्थानीय आवेदन, सहायक दस्तावेज़ अपलोड और संपादन योग्य प्रारूप मॉड्यूल 03 में उपलब्ध हैं।', mr: 'ब्राउझर-स्थानिक अर्ज, सहाय्यक दस्तऐवज अपलोड आणि संपादनयोग्य मसुदे मॉड्यूल 03 मध्ये उपलब्ध आहेत.' },
  benefitTwo: { en: 'Explainable document analysis and file fingerprints support traceable human review.', hi: 'व्याख्यात्मक दस्तावेज़ विश्लेषण और फ़ाइल फ़िंगरप्रिंट ट्रेस योग्य मानवीय समीक्षा में सहायता करते हैं।', mr: 'स्पष्टीकरणासह दस्तऐवज विश्लेषण आणि फाइल फिंगरप्रिंट मागोवा घेता येणाऱ्या मानवी पुनरावलोकनास मदत करतात.' },
  benefitThree: { en: 'Planned rule-linked findings and verification reports in Module 05 to support officer review.', hi: 'अधिकारी समीक्षा के लिए मॉड्यूल 05 में नियम-संबंधित निष्कर्ष और सत्यापन रिपोर्ट नियोजित हैं।', mr: 'अधिकारी पुनरावलोकनासाठी मॉड्यूल 05 मध्ये नियमांशी जोडलेले निष्कर्ष आणि पडताळणी अहवाल नियोजित आहेत.' },
